import json, re

def parse(f):
    # dotnet list package --format json may output multiple JSON objects; grab full content
    with open(f) as fh:
        content = fh.read()
    # Wrap in array if needed
    data = json.loads('[' + content.replace('}{', '},{') + ']') if '}{' in content else [json.loads(content)]
    pkgs = {}
    for d in data:
        for proj in d.get('projects', []):
            pname = proj['path'].split('/')[-1]
            for fw in proj.get('frameworks', []):
                for pkg in fw.get('topLevelPackages', []):
                    pkgs.setdefault(pname, {})[pkg['id']] = pkg['resolvedVersion']
    return pkgs

baseline = parse('baseline-packages.json')
after = parse('after-cpm-packages.json')

print('=== CHANGES ===')
for proj in sorted(set(list(baseline.keys()) + list(after.keys()))):
    bp = baseline.get(proj, {})
    ap = after.get(proj, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(pkg, '-')
        av = ap.get(pkg, '-')
